// v16.xx (feed4), the HUD spec (2026-10-15, section 5 and step 10): THE FEED READS AS A QUIET COLUMN. A line dimmed to 35 percent kept its plate,
// so ten dimmed lines were ten dark boxes. A line now loses its plate as it dims (the plate fades with the line over the same second, the
// words stay at 35 percent, the glyph keeps the kind colour), and in a fight the aged lines dim to 20 percent. FEEDDIM is the level this frame.
var FEEDDIM=0.35;
function feedAlpha(ln){ var age=(G.fd?G.fd.t:0)-ln.at, d=FEEDDIM; return (age<=FEED.hold)?1:Math.max(d,1-(1-d)*(age-FEED.hold)/FEED.fade); }
function feedPlateA(ln){ var age=(G.fd?G.fd.t:0)-ln.at; return (age<=FEED.hold)?1:Math.max(0,1-(age-FEED.hold)/FEED.fade); }

ctx.globalAlpha=oa*feedPlateA(ln)*e;
if(feedPlateA(ln)>0.02) hudPlate(x,yt,w,R.rh,ln.col,HUDC.plate);   // v16.xx (feed4): a dimmed line has no plate
ctx.globalAlpha=oa*al*e;

