{v:'VER',what:'the HUD spec: a feed line loses its plate as it dims, its words stay at 35 percent, and in a fight the aged lines dim to 20 percent',
 run:function(){
   if(!window.__deploy||!window.__endRaid||!window.__frame) return 'SKIP: no raid here';
   if(typeof feedPlateA!=='function'||typeof FEEDDIM==='undefined') return 'this build keeps a plate on every dimmed line';
   var bad=[], g, F, i, plates=[], oHP=hudPlate, oIC=inCombatNow, ys, rows, hasPlate;
   function hasP(y){ for(var j=0;j<plates.length;j++) if(Math.abs(plates[j].y-y)<0.6&&plates[j].a>0.02) return true; return false; }
   function frames(){ plates.length=0; hudPlate=function(x,y,w,h){ plates.push({x:x,y:y,a:ctx.globalAlpha}); return oHP.apply(this,arguments); }; try{ for(var j=0;j<3;j++){ plates.length=0; __frame(0.016); } } finally { hudPlate=oHP; } }
   try{
     __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
     try{ __pinDPR(1); }catch(_d){}
     __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     g=__state(); if(!g||!g.player||g.over) return 'SKIP: no live raid';
     g.bagOpen=false; g.mapOpen=false; g.ents.length=0; keys={};
     say('PLATE TEST ONE','info'); say('PLATE TEST TWO','info'); say('PLATE TEST THREE','info');
     F=feedS(); F.t+=0.5; frames();
     ys=FEEDBOX.rows.map(function(r){ return r.y; });
     if(ys.length<3) return 'SKIP: the feed lines were not drawn';
     for(i=0;i<ys.length;i++) if(!hasP(ys[i])) bad.push('a fresh feed line has no plate (row '+i+')');
     F.t+=FEED.hold+FEED.fade+1; frames();
     ys=FEEDBOX.rows.map(function(r){ return r.y; });
     for(i=0;i<ys.length;i++) if(hasP(ys[i])) bad.push('a dimmed feed line keeps its plate (row '+i+')');
     if(Math.abs(feedAlpha(F.lines[F.lines.length-1])-FEED.dim)>0.001) bad.push('a dimmed line reads '+feedAlpha(F.lines[F.lines.length-1])+', not '+FEED.dim);
     say('PLATE TEST FOUR','info'); F.t+=0.2; frames();
     if(!hasP(FEEDBOX.rows[0].y)) bad.push('the new line at the bottom has no plate');
     inCombatNow=function(){ return true; };
     try{ F.t+=FEED.hold+FEED.fade+1; frames(); } finally { inCombatNow=oIC; }
     if(Math.abs(FEEDDIM-0.2)>0.001) bad.push('the aged lines dim to '+FEEDDIM+' in a fight, not 0.2');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ hudPlate=oHP; inCombatNow=oIC; try{ var g2=__state(); if(g2&&!g2.over){ g2.player.downed=false; __endRaid('abandon'); } }catch(_e){} __topClear(); __cleanProfile(); }
   return bad.length?bad.join('; '):null; }},
